create table CHAUFFEUR
(
    ID      VARCHAR2(255) not null constraint CHAUFFEUR_PK primary key,
    NOM     VARCHAR2(255),
    NUMERO  VARCHAR2(255),
    ADRESSE VARCHAR2(255),
    COMPTE  VARCHAR2(100)
);

ALTER TABLE AS_INGREDIENT_MAINTENANCE ADD  LIBELLE               VARCHAR2(255);
ALTER TABLE AS_INGREDIENT_MAINTENANCE ADD  DATEAQUISITION        DATE;
ALTER TABLE AS_INGREDIENT_MAINTENANCE ADD  PU                    NUMBER(10, 2) default 0;
ALTER TABLE AS_INGREDIENT_MAINTENANCE ADD  NBHEUREDISPONIBILITE  NUMBER;
ALTER TABLE AS_INGREDIENT_MAINTENANCE ADD  NBHEUREDISPONNIBILITE NUMBER;
ALTER TABLE AS_INGREDIENT_MAINTENANCE ADD  IDLIGNE               VARCHAR2(40);

create view COURSELIB as
SELECT
    c.ID,
    c.IDVEHICULE,
    c.IDCHAUFFEUR,
    c.DATY,
    c.REMARQUE,
    c.ETAT,
    CASE
        WHEN c.ETAT = 1
            THEN 'CREE'
        WHEN c.ETAT = 0
            THEN 'ANNULEE'
        WHEN c.ETAT = 11
            THEN 'VISEE'
        END AS ETATLIB,
    v.LIBELLE AS IDVEHICULELIB,
    ch.NOM  AS IDCHAUFFEURLIB
FROM COURSE c
         LEFT JOIN AS_INGREDIENT_MAINTENANCE v ON v.id = c.IDVEHICULE
         LEFT JOIN AS_INGREDIENTS ai ON ai.id = v.IDINGREDIENT
         LEFT JOIN CHAUFFEUR ch ON ch.ID = c.IDCHAUFFEUR;

create view COURSEFILLELIB as
SELECT
    cf.ID,
    cf.IDOBJET,
    cf.DATEDEPART,
    cf.HEUREDEPART,
    cf.DATEARRIVEE,
    cf.HEUREARRIVEE,
    cf.IDPERSONNEL,
    cf.REMARQUE,
    cf.idmere,
    cf.ETAT,
    (lp.NOM || ' ' || lp.PRENOM) AS IDPERSONNELLIB
FROM COURSEFILLE cf
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = cf.IDPERSONNEL
         LEFT JOIN COURSE c ON c.ID = cf.IDMERE;

